let DATA = [], sortKey = 'recommended', sortDir = 1, category = 'all', modality = 'all', query = '';

// recScore + freshness rules come from shared-rules.js (window.FLLM_RULES); the
// row markup comes from shared-rows.js (window.FLLM_ROWS). Both are generated by
// scripts/build.mjs from the single sources scripts/lib/rules.mjs + rows.mjs, so
// the client table can never drift from the server-rendered table.
const { SLA_DAYS, freshnessStatus } = window.FLLM_RULES;

// The sort comparator lives in shared-sort.js (window.FLLM_SORT), serialised
// from scripts/lib/sort.mjs — the same code explorer.test.mjs executes, so the
// column ordering can never drift from its regression tests.

// Row markup lives in shared-rows.js (window.FLLM_ROWS.rowHtml) — the exact
// function build.mjs used to SSR this table. Every provider field is escaped
// inside it before reaching innerHTML.

const { comparator } = window.FLLM_SORT;

// Free-text search over the fields a visitor would type: name, slug, category label, what is free and model names.
function searchText(p) {
  const models = Array.isArray(p.models_free) ? p.models_free : Object.values(p.models_free || {}).flat();
  return [p.name, p.slug, p.category, p.free_tier, p.best_for, ...models, ...(p.modalities || [])].filter(Boolean).join(' ').toLowerCase();
}

// The day the server render is dated by (ASOF in scripts/build.mjs, inlined as "asof" next to the data), in ms; 0 if unknown.
let SSR_NOW = 0;

// The cells of one rowHtml() string: rowHtml writes `<tr role="row">`, five `<td …>…</td>` without nested cells, then `</tr>`.
const rowCells = (html) => html.replace(/^<tr[^>]*>/, '').replace(/<\/tr>$/, '').split('</td>').slice(0, -1).map((c) => c + '</td>');

// First paint, default view: the server already rendered these rows, in this order, dated by SSR_NOW. Rebuilding all of them
// (about 160 KB of markup on the home page) only to move the freshness to the visitor's clock doubled the page's style and
// layout work and was most of its blocking time. Instead only the cells whose markup differs at the visitor's clock (the
// "Verified Nd ago" cell, a "NEW" badge that expired) are replaced, from the same rowHtml(). Returns false, so that the caller
// rebuilds the table as before, whenever the server rows cannot be matched one for one.
function patchServerRows(rows, now) {
  const tbody = document.getElementById('tbody');
  const trs = tbody && tbody.rows ? Array.from(tbody.rows) : [];
  if (!SSR_NOW || !trs.length || trs.length !== rows.length) return false;
  if (rows.some((p, i) => rowSlug(trs[i]) !== p.slug)) return false;
  rows.forEach((p, i) => {
    const live = window.FLLM_ROWS.rowHtml(p, { now });
    const served = window.FLLM_ROWS.rowHtml(p, { now: SSR_NOW });
    if (live === served) return;
    const a = rowCells(live), b = rowCells(served), tr = trs[i];
    if (a.length !== b.length || a.length !== tr.cells.length) { tr.outerHTML = live; return; }
    a.forEach((cell, k) => { if (cell !== b[k]) tr.cells[k].outerHTML = cell; });
  });
  return true;
}

function render(first) {
  const nocard = document.getElementById('f-nocard').checked;
  const nophone = document.getElementById('f-nophone').checked;
  const commercial = document.getElementById('f-commercial').checked;
  const textOnly = document.getElementById('f-text').checked;
  const notrain = document.getElementById('f-notrain').checked;
  const openai = document.getElementById('f-openai').checked;
  const verifiedOnly = document.getElementById('f-verified').checked;

  const needle = query.trim().toLowerCase();
  let rows = DATA.filter(p => {
    if (needle && !searchText(p).includes(needle)) return false;
    if (category !== 'all' && p.category !== category) return false;
    if (modality !== 'all' && !(p.modalities || []).includes(modality)) return false;
    if (nocard && p.card_required !== false) return false;
    if (nophone && p.phone_required !== false) return false;
    if (commercial && p.commercial_ok !== true) return false;
    if (textOnly && p.is_text_llm !== true) return false;
    if (notrain && p.data_policy?.trains_on_prompts !== false) return false;
    if (openai && p.openai_compatible !== true) return false;
    if (verifiedOnly && p.verified !== true) return false;
    return true;
  });

  rows.sort((a, b) => comparator(sortKey, sortDir, a, b));

  const tbody = document.getElementById('tbody');
  const emptyEl = document.getElementById('empty');
  emptyEl.style.display = rows.length ? 'none' : 'block';
  emptyEl.textContent = rows.length ? '' : 'No providers match these filters.';
  // Keep the result count separate from the visible empty-state message.
  document.getElementById('count').textContent = rows.length === DATA.length
    ? `${rows.length} providers`
    : `Showing ${rows.length} of ${DATA.length} providers`;
  const activeCount = (query.trim() ? 1 : 0) + (category !== 'all' ? 1 : 0) + 
    (modality !== 'all' ? 1 : 0) +
    (sortKey !== 'recommended' ? 1 : 0) +
    [nocard, nophone, commercial, textOnly, notrain, openai, verifiedOnly].filter(Boolean).length;
  document.getElementById('clearFilters').hidden = activeCount === 0;
  syncEmptyClear(emptyEl, rows.length === 0 && activeCount > 0);

  // Rows come from shared-rows.js — the same function the server used to SSR
  // this table (see lib/rows.mjs). Date.now() gives visitors live freshness;
  // the server render uses ASOF for a deterministic initial paint. The first paint of the default view keeps the server rows.
  const now = Date.now();
  if (!(first && activeCount === 0 && patchServerRows(rows, now))) {
    tbody.innerHTML = rows.map((p) => window.FLLM_ROWS.rowHtml(p, { now })).join('\n');
  }
  syncSortSel();
  syncRoving();
  syncURL();
}

// --- keyboard navigation (#174): roving tabindex over the rows ---
// One row is in the tab order (tabindex=0), the rest are tabindex=-1. Arrow
// Up/Down move between rows, Home/End jump to the first/last row, and Enter on
// a row opens its provider page. The movement rule is rowKeyTarget in
// shared-rows.js (lib/rows.mjs), the same code explorer.test.mjs executes.
// Tab/Shift+Tab are never intercepted and the provider links stay in the tab
// order, so there is no keyboard trap; keys with a modifier, and every other
// key (including the "/" a site-wide shortcut would use), pass through.
const { rowKeyTarget } = window.FLLM_ROWS;
let activeSlug = null;
const rowLink = (tr) => tr.querySelector('td.name a[href]');
const rowSlug = (tr) => { const a = rowLink(tr); return a ? a.getAttribute('href').replace(/^p\//, '') : null; };
function setActiveRow(tr) {
  const trs = Array.from(document.getElementById('tbody').rows);
  trs.forEach((r) => { r.tabIndex = r === tr ? 0 : -1; });
  activeSlug = tr ? rowSlug(tr) : null;
}
function syncRoving() {
  const trs = Array.from(document.getElementById('tbody').rows);
  // Keep the same provider active across re-sorts and filters; else the first row.
  setActiveRow(trs.find((tr) => activeSlug && rowSlug(tr) === activeSlug) || trs[0] || null);
}
document.getElementById('tbody').addEventListener('keydown', (e) => {
  if (e.altKey || e.ctrlKey || e.metaKey || e.shiftKey) return;
  const tbody = e.currentTarget;
  const tr = e.target.closest('tr');
  if (!tr || tr.parentNode !== tbody) return;
  const onRow = e.target === tr;
  if (e.key === 'Enter') {
    // Enter on a link already follows it natively; on the row, follow its link.
    const a = onRow && rowLink(tr);
    if (a) { e.preventDefault(); a.click(); }
    return;
  }
  // Home/End only move rows when a row itself has focus.
  if (!onRow && (e.key === 'Home' || e.key === 'End')) return;
  const trs = Array.from(tbody.rows);
  const next = rowKeyTarget(e.key, trs.indexOf(tr), trs.length);
  if (next === null) return;
  e.preventDefault();
  setActiveRow(trs[next]);
  trs[next].focus();
});
document.getElementById('tbody').addEventListener('focusin', (e) => {
  const tr = e.target.closest('tr');
  if (tr && tr.parentNode === e.currentTarget) setActiveRow(tr);
});
// The server-rendered rows are navigable before (or without) a client repaint.
syncRoving();

// The status of the oldest verification in words, so it never rests on colour alone.
const STATUS_WORD = { fresh: 'fresh', due: 'due for re-check', stale: 'stale' };
function renderStats(first) {
  const html = statsHtml(Date.now());
  // The server wrote the same tiles dated by SSR_NOW: leave them alone unless the visitor's clock changes them.
  if (first && SSR_NOW && html === statsHtml(SSR_NOW)) return;
  document.getElementById('stats').innerHTML = html;
}
function statsHtml(now) {
  const total = DATA.length;
  const ongoing = DATA.filter(p => p.category === 'ongoing').length;
  const trial = DATA.filter(p => p.category === 'trial').length;
  const ages = DATA.filter(p => p.verified && p.last_verified).map(p => Math.floor((now - Date.parse(p.last_verified + 'T00:00:00Z')) / 86400000));
  const oldest = ages.length ? Math.max(...ages) : 0;
  const slaDays = SLA_DAYS || 90;
  const status = freshnessStatus(oldest);
  const tiles = [
    ['ic-database', total, 'providers tracked', ''],
    ['ic-refresh', ongoing, 'ongoing free tiers', ''],
    ['ic-clock', trial, 'trial credits', ''],
    ['ic-shield', `${oldest}d`, `oldest verification · ${slaDays}-day SLA`, status],
  ];
  return tiles.map(([ic, n, l, c]) =>
    `<div class="stat ${c}"><svg class="si" aria-hidden="true"><use href="#${ic}"/></svg><div class="num">${n}</div><div class="lbl">${l}${c ? `<span class="sr-only"> (${STATUS_WORD[c] || c})</span>` : ''}</div></div>`).join('');
}

// On small screens the column headers are hidden, so a select offers the same sorts.
function syncSortSel() {
  const sel = document.getElementById('sortSel');
  if (!sel) return;
  const v = sortKey + ':' + sortDir;
  // Sorts the select does not offer (e.g. ?sort=notes, or a reversed column) show the placeholder.
  sel.value = [...sel.options].some(o => o.value === v && !o.disabled) ? v : 'custom';
}
document.getElementById('sortSel').addEventListener('change', e => {
  const [key, dir] = e.target.value.split(':');
  sortKey = key; sortDir = Number(dir);
  document.querySelectorAll('thead th').forEach(h => { h.classList.remove('sorted', 'asc'); h.setAttribute('aria-sort', 'none'); });
  const th = document.querySelector('thead th[data-key="' + key + '"]');
  if (th) {
    th.classList.add('sorted'); th.classList.toggle('asc', sortDir === 1);
    th.setAttribute('aria-sort', sortDir === 1 ? 'ascending' : 'descending');
  }
  render();
});

function applySort(th) {
  const key = th.dataset.key;
  if (sortKey === key) sortDir *= -1; else { sortKey = key; sortDir = 1; }
  document.querySelectorAll('thead th').forEach(h => { h.classList.remove('sorted', 'asc'); h.setAttribute('aria-sort', 'none'); });
  th.classList.add('sorted'); if (sortDir === 1) th.classList.add('asc');
  th.setAttribute('aria-sort', sortDir === 1 ? 'ascending' : 'descending');
  render();
}

document.querySelectorAll('#cat button').forEach(btn => btn.addEventListener('click', () => {
  document.querySelectorAll('#cat button').forEach(b => { b.classList.remove('active'); b.setAttribute('aria-pressed', 'false'); });
  btn.classList.add('active'); btn.setAttribute('aria-pressed', 'true');
  category = btn.dataset.cat; render();
}));
// Each sortable header holds a real button: Enter and Space click it natively and the click reaches the header cell.
document.querySelectorAll('thead th[data-key]').forEach(th => {
  th.addEventListener('click', () => applySort(th));
});
['f-nocard', 'f-nophone', 'f-commercial', 'f-text', 'f-notrain', 'f-openai', 'f-verified'].forEach(id =>
  document.getElementById(id).addEventListener('input', e => {
    const chip = e.target.closest('.chip'); if (chip) chip.classList.toggle('on', e.target.checked);
    render();
  }));

// --- shareable state: sync filters to the URL and restore them on load ---
const URL_FLAGS = [['nocard', 'f-nocard'], ['nophone', 'f-nophone'], ['commercial', 'f-commercial'], ['text', 'f-text'], ['notrain', 'f-notrain'], ['openai', 'f-openai'], ['verified', 'f-verified']];
function syncURL() {
  const params = new URLSearchParams();
  if (query.trim()) params.set('q', query.trim());
  if (category !== 'all') params.set('cat', category);
  if (modality !== 'all') params.set('mod', modality);
  if (sortKey !== 'recommended') {
    params.set('sort', sortKey);
    params.set('dir', sortDir === 1 ? 'asc' : 'desc');
  }
  URL_FLAGS.forEach(([k, id]) => { if (document.getElementById(id).checked) params.set(k, '1'); });
  const qs = params.toString();
  history.replaceState(null, '', qs ? '?' + qs : location.pathname);
}
function applyURL() {
  const params = new URLSearchParams(location.search);
  // ?compare=a,b on the home page opens the compare view (#175), which owns
  // the slug parsing and validation (lib/compare.mjs).
  if (params.has('compare')) {
    location.replace('compare/?compare=' + encodeURIComponent(params.get('compare')).replace(/%2C/gi, ','));
    return;
  }
  const q = params.get('q');
  if (q) { query = q; document.getElementById('q').value = q; }
  const cat = params.get('cat');
  if (cat && ['all', 'ongoing', 'trial'].includes(cat)) {
    category = cat;
    document.querySelectorAll('#cat button').forEach(b => {
      const on = b.dataset.cat === cat; b.classList.toggle('active', on); b.setAttribute('aria-pressed', String(on));
    });
  }
  const mod = params.get('mod');
  const modSel = document.getElementById('modality');
  if (mod && [...modSel.options].some(o => o.value === mod)) { modality = mod; modSel.value = mod; }
  URL_FLAGS.forEach(([k, id]) => {
    if (params.get(k) === '1') { const el = document.getElementById(id); el.checked = true; const chip = el.closest('.chip'); if (chip) chip.classList.add('on'); }
  });
  const sort = params.get('sort');
  const dir = params.get('dir');
  if (sort && ['recommended', 'name', 'category', 'free_tier', 'notes', 'verified'].includes(sort)) {
    sortKey = sort;
    sortDir = dir === 'desc' ? -1 : 1;
    const th = document.querySelector(`thead th[data-key="${sort}"]`);
    if (th) {
      th.classList.add('sorted');
      th.classList.toggle('asc', sortDir === 1);
      th.setAttribute('aria-sort', sortDir === 1 ? 'ascending' : 'descending');
    }
  }
}
applyURL();

document.getElementById('q').addEventListener('input', e => { query = e.target.value; render(); });
document.getElementById('modality').addEventListener('change', e => { modality = e.target.value; render(); });

function resetControls() {
  query = ''; document.getElementById('q').value = '';
  category = 'all';
  document.querySelectorAll('#cat button').forEach(b => { const on = b.dataset.cat === 'all'; b.classList.toggle('active', on); b.setAttribute('aria-pressed', String(on)); });
  modality = 'all'; document.getElementById('modality').value = 'all';
  URL_FLAGS.forEach(([, id]) => { const el = document.getElementById(id); el.checked = false; const chip = el.closest('.chip'); if (chip) chip.classList.remove('on'); });
}
// The pinned filter bar's real height (it wraps) keeps a focused row from sitting under it: the style sheet reads --controls-h.
(() => {
  const bar = document.querySelector('.controls');
  if (!bar || typeof ResizeObserver === 'undefined') return;
  new ResizeObserver(() => document.documentElement.style.setProperty('--controls-h', Math.round(bar.getBoundingClientRect().height) + 'px')).observe(bar);
})();
function clearAll() {
  resetControls();
  sortKey = 'recommended'; sortDir = 1;
  document.querySelectorAll('thead th').forEach(h => { h.classList.remove('sorted', 'asc'); h.setAttribute('aria-sort', 'none'); });
  render();
  // Both clear buttons hide themselves once nothing is filtered: keep the keyboard focus on the page.
  document.getElementById('q').focus();
}
// An empty result offers the way out where the reader is looking: a "Clear all filters" button right under
// the empty message. It is created on first need (the page works without it) and hidden whenever rows show.
function syncEmptyClear(emptyEl, show) {
  let btn = document.getElementById('emptyClear');
  if (!btn) {
    if (!show || typeof document.createElement !== 'function' || !emptyEl || typeof emptyEl.after !== 'function') return;
    btn = document.createElement('button');
    btn.type = 'button';
    btn.id = 'emptyClear';
    btn.className = 'clear-btn empty-clear';
    btn.textContent = 'Clear all filters';
    btn.addEventListener('click', clearAll);
    emptyEl.after(btn);
  }
  btn.hidden = !show;
}
document.getElementById('clearFilters').addEventListener('click', clearAll);
// The dataset is inlined at build time (see #providers-data) so the table is server-rendered
// and the page needs no network round-trip. Fall back to fetch only if the inline data is absent.
const SOURCES = ['providers.json', 'https://raw.githubusercontent.com/pacocartones/free-llm-api-hub/main/data/providers.json'];
(async () => {
  const inlineEl = document.getElementById('providers-data');
  try {
    const raw = inlineEl && inlineEl.textContent.trim();
    if (raw) {
      const inline = JSON.parse(raw);
      DATA = inline.providers;
      const asof = typeof inline.asof === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(inline.asof) ? Date.parse(inline.asof + 'T00:00:00Z') : NaN;
      SSR_NOW = asof > 0 ? asof : 0;
      renderStats(true); render(true); return;
    }
  } catch (_) { /* fall through to fetch */ }
  for (const url of SOURCES) {
    try {
      const r = await fetch(url); if (!r.ok) continue;
      DATA = (await r.json()).providers;
      renderStats(); render(); return;
    } catch (_) { /* try next */ }
  }
  // The server-rendered table remains available if a client-side refresh cannot
  // load data. Do not replace it with a transport-level error message.
})();
